#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Applying real OMED branding: app icon, adaptive icon, splash icon, favicon, app name..."
mkdir -p assets

echo "  assets/icon.png"
mkdir -p "$(dirname 'assets/icon.png')"
echo '' | base64 --decode > 'assets/icon.png'

echo "  assets/adaptive-icon.png"
mkdir -p "$(dirname 'assets/adaptive-icon.png')"
echo '' | base64 --decode > 'assets/adaptive-icon.png'

echo "  assets/splash-icon.png"
mkdir -p "$(dirname 'assets/splash-icon.png')"
echo '' | base64 --decode > 'assets/splash-icon.png'

echo "  assets/favicon.png"
mkdir -p "$(dirname 'assets/favicon.png')"
echo '' | base64 --decode > 'assets/favicon.png'

echo "  app.json"
mkdir -p "$(dirname 'app.json')"
echo '' | base64 --decode > 'app.json'

echo ""
echo "Done. Note: icon changes only take effect in a fresh native build (EAS build or a new dev client) - they will NOT show up in an already-running Expo Go session."
